-- S7 阶段3：链接 Folder 行 + 树链接（在 s7-migrate-libs.sql + 首启实例之后执行）
ON CONFLICT DO NOTHING;

-- 直接子项重挂：parent lib → 链接 Folder（名字映射 movie-lib-001 ↔ movie001）
UPDATE media_items m SET parent_id = f.id
FROM media_items f, media_items l
WHERE f.type = 1 AND l.type = 0 AND m.parent_id = l.id
  AND f.name = replace(l.name, '-lib-', '')
  AND m.type IN (2, 3, 7, 8, 9, 20);

-- top_parent → 链接 Folder guid（直接子项），中间层从父级传播
UPDATE media_items m SET top_parent_id = f.guid::text
FROM media_items f
WHERE m.parent_id = f.id AND f.type = 1 AND m.type IN (2,3,7,8,9,20);
UPDATE media_items m SET top_parent_id = p.top_parent_id
FROM media_items p
WHERE m.parent_id = p.id AND p.top_parent_id IS NOT NULL AND m.top_parent_id IS NULL;

-- 祖先补全：folder（所有媒体，经 lib 映射）+ root
SELECT a.item_id, f.id, 1
FROM ancestor_ids a
JOIN media_items l ON l.id = a.ancestor_id AND l.type = 0
JOIN media_items f ON f.type = 1 AND f.name = replace(l.name, '-lib-', '')
ON CONFLICT DO NOTHING;
SELECT a.item_id, 1, 0 FROM ancestor_ids a JOIN media_items l ON l.id = a.ancestor_id AND l.type = 0
ON CONFLICT DO NOTHING;

-- 验收
SELECT 'folders' AS check, count(*) FROM media_items WHERE type = 1;
SELECT 'media_with_folder_parent', count(*) FROM media_items m JOIN media_items f ON f.id = m.parent_id AND f.type = 1 WHERE m.type IN (2,3,7,8,9,20);
SELECT 'media_with_folder_topparent', count(*) FROM media_items m JOIN media_items f ON f.guid::text = m.top_parent_id AND f.type = 1 WHERE m.type IN (2,3,4,5,6,7,8,9,20);
